-- BIT-75-02 POSTFLIGHT (solo lectura). Conforme = todas las filas 'OK' (las 'VER' son informativas).
SELECT 'perfiles: SELECT/INSERT/UPDATE en id,nombre,rol,activo' AS chequeo, CASE WHEN (SELECT bool_and(has_column_privilege('service_role','public.perfiles',c,p)) FROM unnest(ARRAY['id','nombre','rol','activo']) c, unnest(ARRAY['SELECT','INSERT','UPDATE']) p) THEN 'OK' ELSE 'FALLA' END AS resultado
UNION ALL SELECT 'perfiles: sin acceso a persona_id/created_at/updated_at, sin DELETE', CASE WHEN NOT (SELECT bool_or(has_column_privilege('service_role','public.perfiles',c,p)) FROM unnest(ARRAY['persona_id','created_at','updated_at']) c, unnest(ARRAY['SELECT','INSERT','UPDATE']) p) AND NOT has_table_privilege('service_role','public.perfiles','DELETE') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'establecimientos: solo SELECT(id)', CASE WHEN has_column_privilege('service_role','public.establecimientos','id','SELECT') AND NOT has_column_privilege('service_role','public.establecimientos','nombre','SELECT') AND NOT has_any_column_privilege('service_role','public.establecimientos','INSERT,UPDATE') AND NOT has_table_privilege('service_role','public.establecimientos','DELETE') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'establecimientos_usuarios: SELECT+INSERT columnas, DELETE, sin UPDATE', CASE WHEN (SELECT bool_and(has_column_privilege('service_role','public.establecimientos_usuarios',c,p)) FROM unnest(ARRAY['perfil_id','establecimiento_id']) c, unnest(ARRAY['SELECT','INSERT']) p) AND has_table_privilege('service_role','public.establecimientos_usuarios','DELETE') AND NOT has_any_column_privilege('service_role','public.establecimientos_usuarios','UPDATE') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'bit56_validadores: solo lectura de perfil_id,establecimiento_id', CASE WHEN (SELECT bool_and(has_column_privilege('service_role','public.bit56_validadores',c,'SELECT')) FROM unnest(ARRAY['perfil_id','establecimiento_id']) c) AND NOT has_any_column_privilege('service_role','public.bit56_validadores','INSERT,UPDATE') AND NOT has_table_privilege('service_role','public.bit56_validadores','DELETE') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'usuarios_auditoria: service_role solo SELECT/INSERT (sin cambios)', CASE WHEN has_table_privilege('service_role','public.usuarios_auditoria','SELECT') AND has_table_privilege('service_role','public.usuarios_auditoria','INSERT') AND NOT (has_table_privilege('service_role','public.usuarios_auditoria','UPDATE') OR has_table_privilege('service_role','public.usuarios_auditoria','DELETE')) THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'anon sin SELECT/INSERT/UPDATE/DELETE en las 5 tablas', CASE WHEN NOT (SELECT bool_or(has_table_privilege('anon',t,p)) FROM unnest(ARRAY['public.perfiles','public.establecimientos','public.establecimientos_usuarios','public.bit56_validadores','public.usuarios_auditoria']) t, unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) p) THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'huella privilegios anon/authenticated SIN CAMBIOS (md5 7b69a42e062cb95d3fd63964c089d343)', CASE WHEN (SELECT md5(coalesce(string_agg(x, ';' ORDER BY x),'')) FROM (SELECT c.relname::text||'|'||a.grantee::regrole::text||'|'||a.privilege_type AS x FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid IN ('public.perfiles'::regclass,'public.establecimientos'::regclass,'public.establecimientos_usuarios'::regclass,'public.bit56_validadores'::regclass,'public.usuarios_auditoria'::regclass) AND a.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('anon','authenticated')) UNION ALL SELECT c.relname::text||'.'||att.attname::text||'|'||a.grantee::regrole::text||'|'||a.privilege_type FROM pg_attribute att JOIN pg_class c ON c.oid=att.attrelid CROSS JOIN LATERAL aclexplode(att.attacl) a WHERE att.attacl IS NOT NULL AND c.oid IN ('public.perfiles'::regclass,'public.establecimientos'::regclass,'public.establecimientos_usuarios'::regclass,'public.bit56_validadores'::regclass,'public.usuarios_auditoria'::regclass) AND a.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('anon','authenticated'))) s) = '7b69a42e062cb95d3fd63964c089d343' THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'RLS activo en las 5 tablas', CASE WHEN (SELECT count(*) FROM pg_class WHERE oid IN ('public.perfiles'::regclass,'public.establecimientos'::regclass,'public.establecimientos_usuarios'::regclass,'public.bit56_validadores'::regclass,'public.usuarios_auditoria'::regclass) AND relrowsecurity) = 5 THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'triggers intactos (BIT-56-03 A, ultimo admin A, auditoria inmutable, guard designacion)', CASE WHEN EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.perfiles'::regclass AND tgname='bit56_proteger_perfiles' AND tgenabled='A') AND EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.perfiles'::regclass AND tgname='bit75_proteger_ultimo_admin' AND tgenabled='A') AND EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.usuarios_auditoria'::regclass AND tgname='bit75_auditoria_inmutable') AND EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.bit56_validadores'::regclass AND tgname='bit56_guard_designacion') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'funciones bit75 solo service_role (sin cambios)', CASE WHEN has_function_privilege('service_role','public.bit75_listar_usuarios()','EXECUTE') AND has_function_privilege('service_role','public.bit75_buscar_usuario(text)','EXECUTE') AND NOT (has_function_privilege('authenticated','public.bit75_listar_usuarios()','EXECUTE') OR has_function_privilege('anon','public.bit75_listar_usuarios()','EXECUTE') OR has_function_privilege('authenticated','public.bit75_buscar_usuario(text)','EXECUTE') OR has_function_privilege('anon','public.bit75_buscar_usuario(text)','EXECUTE')) THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'recuento perfiles/vinculos/validadores/atenciones/auditoria (comparar con preflight)', 'VER ' || (SELECT count(*) FROM public.perfiles)::text||'/'||(SELECT count(*) FROM public.establecimientos_usuarios)::text||'/'||(SELECT count(*) FROM public.bit56_validadores)::text||'/'||(SELECT count(*) FROM public.atenciones_clinicas)::text||'/'||(SELECT count(*) FROM public.usuarios_auditoria)::text;
